import math


def plain(cents: int) -> str:
    """Money as digits: 1250 is "12.50"."""
    sign = "-" if cents < 0 else ""
    whole, part = divmod(abs(cents), 100)
    return f"{sign}{whole}.{part:02d}"


def fmt(cents: int) -> str:
    """Money as text: 1250 is "$12.50"."""
    return "$" + plain(cents)


def pct(cents: int, rate: float) -> int:
    """An amount times a rate, rounded half up."""
    return math.floor(cents * rate + 0.5)


def avg(total: int, n: int) -> int:
    """An average rounded half up: 0 when there is nothing to average."""
    if n <= 0:
        return 0
    return (2 * total + n) // (2 * n)

